    exMegalodon: 'Megalodon:',
    exSaves: 'बचत:',
    walletCaption: 'गूगल, एप्पल, टेलीग्राम, ईमेल, एसएमएस या पासबी के साथ साइन अप करें और कुछ क्लिक में आपके लिए एक वॉलेट उत्पन्न करें । & nbspमोका ऍकर तनिकउ चिंता नाहीं बा कि तू लोग मोर निआव करा या मनइयन क कउनउ अउर अदालत ।',
    accountsDesc: 'एह में कई गो तरीका बा आ एह में से केहू के अपना पर्स के जरूरत नइखे. गूगल, एप्पल या टेलीग्राम के साथ साइन इन करें, अपने ईमेल पता या एसएमएस के माध्यम से भेजे गए कोड के साथ, आपके फोन या कंप्यूटर पर पासवर्ड के साथ, या आप पहले से ही उपयोग कर रहे पर्स को जोड़कर । & nbspकाहेकि वॉलेट के अलावा सब कुछ पृष्ठभूमि में आपके लिए एक गैर - रखरखाव वॉलेट उत्पन्न करता हैः आप कुंजी रखते हैं, हम कभी भी हिरासत में नहीं लेते, और गैस प्रायोजित होता है, ताकि आप कभी भी देशी टोकन खरीदने के बिना पोस्ट, टिप और इकट्ठा कर सकें । रउआ लोग से सलाह बा कि कृपया कौनो लेख पर हस्ताक्षर ना करब ।',
    accountsB1Desc: 'गूगल, एप्पल या टेलीग्राम, एगो टॅप, आपके खातिर बनावल गइल वॉलेट आ पहिला पोस्ट से प्रायोजित गैस ।',
    accountsB3Desc: 'MetaMask, Rainbow, Trust, Phantom या कुछ भी WalletConnect से बात करें, और पता साबित करने के लिए एक बार साइन करें । अगर कौनो फ़ैंटम साइन-इन इन अस्वीकार कर दिहल गइल बा काहे कि एकर Ethereum पता के कवनो इतिहास नइखे, त आप आपन सोलाना वॉलेट के साबित कर सकत बानी । उ पचे नगर क बचावइ क जतन मँ बहोत थक जइहीं, किन्तु उ पचे लपटन क सिरिफ ईर्धन होइहीं ।',
    accountsB5Desc: 'नया सदस्यन के निर्देशिका में जमीन के जोड़े वाला हर आदमी आपन पहिलका तीस दिन खातिर आपन नाम के बगल में एगो नया सदस्य के चिप लेके आवे ला, ताकि समुदाय उनका के देख सके आ उनका के स्वागत कर सके । नया सदस्य लोग के भी वैकल्पिक मार्गदर्शन कइल जाला, जेकरा के बाद में सेटिंग्स से फिर से खोलल जा सके ला ।',
    accountsB6: 'पन्ना जेवन "टेम्पलेटःCount',
    accountsB6Desc: '"फिंगरप्रिंट के साथ जारी रखें" चुनें और पासवर्ड खुद खाता है — कोई ईमेल, कोई फोन नंबर, कोई पासवर्ड नहीं । एंड्रॉयड एप्लिकेशन में भी काम करें.',
    accountsB7: 'अनुकूलित करें या अनुकूलित करेंः',
    accountsB7Desc: 'साइन-इन शीट में आपके पास पहिले से मौजूद वॉलेट की कुंजी आयात करे औरु पहिले से मौजूद DeHub खाते के माइग्रेट करे क खातिर अलग अलग विकल्प होला, एही से नया साइन-अप के इनहन में से केहू के चुने के जरुरत ना पड़ेला ।',
    accountsB8: 'चल रहे:',
    accountsB8Desc: 'आप अपने पोस्ट में Image जरूर Use करें लेकिन याद रहे Image Copyright Free हो. राउर प्रोफाइल, अपलोड आ स्टोरेज मीडिया, बैकअप कॉपी समेत हटा दिहल गइल बा, आ एप्पल लिंक से साइन इन रद्द कर दिहल गइल बा । एगो सार्वजनिक ब्लॉकचेन के बारे में जवन कुछ भी लिखल गइल बा ऊ अबही जारी बा ।',
    uploadGallery: 'एगो पोस्ट एक के बजाय कई गो फोटो ले जा सकेलाः चार गो बिना बैज के, हर बैज लेयर के साथ मेगालोडन में बीस ले बढ़ के, आ हर फोटो 42.069 एमबी तक हो सकेला. रचनाकार में भेजने, खींचने या लिखने से पहले, चित्रों को क्रम में खींचें, और मूल फ़ाइल को पूर्ण संकल्प, पिंच और ज़ूम में देखने के लिए किसी भी फोटो फुलस्क्रीन खोलें ।',
    labelComposerTools: 'भरवां करेला रेसिपीः',
    uploadComposerTools: 'चित्र या वीडियो सीधे संगीतकार में पेस्ट करें, पूरा पोस्ट को एक ड्राफ्ट के रूप में सहेजें, बाद के लिए इसे शेड्यूल करें (अपने प्रोफ़ाइल पर अनुसूचित पोस्ट दिखाएं), इसे "बच्चों के लिए बनाया गया" या परिपक्व चिह्नित करें, और इसे एक ही चरण में अपने अन्य सामाजिक खातों में भेजें । बाद में एह पोस्ट के संपादन से हटा दिहल जा सकत बा ।',
    profileB1: 'स्तर समायोजित करेंः:',
