    badgeUnlock4: 'सुपर पावर, प्रोफ़ाइल सौंदर्य प्रसाधन, अधिक प्रोफ़ाइल स्लॉट, प्रति पोस्ट अधिक चित्र, और अपने खुद के इमोजी, स्टिकर और GIF पैक ।',
    tipDesc3: 'टिप्स पोस्ट, टिप्पणी, डायरेक्ट मैसेज अउरी लाइव स्ट्रीम पर काम करेला. अगर आप DeHub टोकन से छोटा हैं, तो टिप शीट आपके अन्य संतुलन प्रदान करता है — USDC, ETH या आधार पर टोकन, BnB चेन, Robinhood चेन या आर्क — और उन्हें टिप से पहले आपके लिए परिवर्तित करें । एक बार जब आप एगो पोस्ट लिखले बानी तब एकर टिप बटन एगो चमकदार हीरा के दिखावेला जेहसे आप देख सकत बानी कि आप पहिले से ही कहां भेजले बानी ।',
    liveStreamDesc: 'अपने ब्राउज़र में, पोस्ट कंपोजर से, या फिर एन्कोडर से लाइव जायें । स्ट्रीम्स डीहब के आपन इन्वेस्ट पर प्रकाशित करेलन आउर वेबआरटीसी पर लगभग वास्तविक समय में खेलेलन, लाइवपीर के साथे एगो स्वचालित फालबैक के रूप में जब एगो नेटवर्क इन्वेस्ट तक ना पहुँच सकेला. हर प्रवाह अनुमतहीन बा आ सेंसरशिप प्रतिरोधी बा, एकर आपन चैट बा, आ जब ई खतम हो जाला तब एकर पुनरावृत्ति हो जाला ।',
