    spDescTeamUp: 'सब कुछ के बारे में सब कुछ/वित्त/बिजली बिल जमा करें । टीम में सब लोग बैज पहन रहे हैं, कुल संतुलन अनलॉक, और यह कुछ भी नहीं लागत है । एगो टीम प्राइवेट हो सकेला, एही से लोग शामिल होखे के मांग करत बा आ मालिक ओकरा के मंजूरी दे देत बा.',
    feedsHomeDesc: 'पाठ, चित्र, लेख, वीडियो, ऑडियो और लाइव पोस्ट के मिश्रित फ़ीड । लाइक, टिप्पणी, रिपॉस्ट, उद्धरण, बुकमार्क आउर टोकन टिपिंग हर कार्ड में बनावल जाला, आउर पोस्ट के गेट कइल जा सकेला, पे-पर-व्यू कइल जा सकेला, या watch2earn खातिर सेट करल जा सकेला. कौनो भी एकरा के बाढ़ ना पहुँचावे खातिर, होम फीड में प्रति लेखक के रोजाना सीमित संख्या में पोस्ट होखेलाः एगो बैज के बिना आउर एगो बैज के स्तर खातिर, मेगालोडोन में चौदह तक. लेखक के प्रोफाइल पर सब कुछ दिखाई दे रहा है, और फिर भी ।',
    feedsSort: 'समायोजित करें और फ़िल्टर करेंः',
    feedsSortDesc: 'अंतिम क्रम टैब में सबसे पहिले आवेला, एकरे बाद अधिकांश सुझाव सहित सगाई के प्रकार होला. हशटैग फ़िल्टर करे खातिर, रउआ पहिले से देख चुकल वीडियो सभ के चिह्नित आ छिपावल जा सकत बा, आ कवनो भी लाइव स्टेज सभ के घर के चोटी पर रखल जा सकत बा ।',
