    feedsCommentsDesc: 'हर पोस्ट के आपन पसंद, नापसंद आ गिनती होखे के चाहीं । एह पर आपन जबाब देवे खातिर एगो कमेंट पर क्लिक करीं । जब एगो लेखक खुद के जबाब देला त रन एगो संख्यात्मक तार बन जाला. एगो निर्माता आपन खुद के पोस्ट पर एगो टिप्पणी डाल सकेला; तार तब ओह पिन के साथे ले जाला, फिर एगो सशुल्क टिप्पणी एंकर, फिर पाँच गो सबसे प्रयुक्त टिप्पणी. रचनाकार एगो पोस्ट खातिर सामान्य जमीन मोड चालू कर सकत हव, जे पाठक लोगन के आपन पहिलका उत्तर से पहिले दुसरका तरफ के सबसे मजबूत बिंदु के मांग करेला, आउर टिप्पणी बॉक्स में एआई बटन आपके स्वर के जाँच करेला, ओकर शैली बदल सकेला या वर्तनी आउर व्याकरण के ठीक करेला. इ दावे का एक संग्रहीत संस्करण यहां देखअल जा सकेला है और एकर आशुचित्र नीचे देवल गइल बा ।',
