    daoB2Desc: '3 काहेकि तू पचे ऍतना मूरख होइ सकत ह, जउने जीवन क तू सबइ आतिमा स आरम्भ किहे रह्या-ओका अब हाड़-मांस क सरीर एह श्रेणी के हटावल न जाय; फिलहाल ई खाली बा ।',
    daoB3: 'सुझावल गइल प्रस्तावः',
    daoB3Desc: 'योगदानकर्ता सीधे खजाना के पन्ना से खजाना के खजाना के खर्चा कइसे कइल जाला, एकर प्रस्ताव पर वोट डालें आ वोट डालें ।',
    moreB3Desc: 'लाइव साइट आँकड़ा — आगंतुक, पन्ना दृश्य अउरी समुदाय संख्या, दिन, साल या समय के हिसाब से — एकही पन्ना पर एगो स्थायी फीडबैक हब के साथे आंतरिक रूप से रखे के बजाय प्रकाशित कइल गइल बा.',
