    spNoAllowance: 'नाहीं देहीं भत्ता',
    spPowersLead: '4. बैज सीढ़ी के हर रस्सी ठीक एक शक्ति खोलता, आउर आपके द्वारा खोलल गईल प्रत्येक शक्ति खुला रहेला. उ पचे एक ही पन्द्रह दिना मँ एक ही भत्ता क उपयोग करत हीं, एह बरे इ तय करत ह कि उ पचे का खर्च करिहीं ।',
    spRotationDesc: 'प्याज के बजाय प्याज के सेवन करे । जब कई बूस्ट एक साथ चलेला, त हर दर्शक के एक के इलाज कइल जाला, जेकरा के बूस्टर के बैज लेयर द्वारा भारित कइल जाला — एगो उच्च स्तर के अधिक बार प्रदर्शित कइल जाला, आउर सभे के अभी भी उ खिड़की मिल जाला जेकरा खातिर उ भुगतान कइलें. एगो प्रोत्साहन खरीदल एगो निश्चित संख्या खातिर आवाज के हिस्सा ह, फ़ीड के ऊपरी हिस्सा के खाली स्वामित्व ना.',
    spRotationTitle: 'कइसे बांटत बा',
    spSafetyDesc: 'हर ड्रॉ के पोस्ट के मुकाबले फिर से जाँच कइल जाला काहे कि ई ओह समय मौजूद बा, एही से एगो पोस्ट जवन तब से हटावल गइल बा, ब्लॉक कइल गइल बा या चिह्नित कइल गइल बा, ऊ अजनबी के फ़ीड तक कबो ना पहुँचल बा । पुरानी पोस्ट भी बुकिंग में अस्वीकार कर दिया जाता है, और एक बूस्ट कभी भी किसी के लिए नहीं किया जाता जो आपको ब्लॉक करता है, या किसी के लिए जो आपने हौसला बढ़ाया है ।',
