    intro: 'डेहब टोकन डेहब नेटवर्क के मूल उपयोगिता के सिक्का हवे; डीएचबी एकर टिकर प्रतीक हवे । ई हर d\'app पर खाता के एकल इकाई ह — जवन चीज से आप टाइप कर सकत बानी, सामग्री के अनलॉक कर सकत बानी, देख सकत बानी आ बना सकत बानी, आ AI पीढ़ी पर खर्च कर सकत बानी । चूँकि उ सब चेन पर रहत बा, इकोसिस्टम में मूल्य के हर आंदोलन एगो निजी लेजर में बैठला के बजाय सार्वजनिक रूप से सत्यापित कइल जा सकेला.',
    pegDesc1: 'डिस्काउंट एगो उपयोगी टेम्पलेट हवे । इन-ऐप के प्रयोजन खातिर ई वर्तमान में $ 0.001 प्रति टोकन पर पेग कइल गइल बा, जवन कि फिएट गेटवे के माध्यम से खरीदारी करे पर देखल जाए वाला दर आ इन-ऐप मूल्य निर्धारण खातिर इस्तेमाल होखे वाला दर बा । ई नेटवर्क के स्केल करे के समय इन-ऐप अर्थव्यवस्था के स्थिर आउर पूर्वानुमान योग्य रखे खातिर मौजूद बा — ई एगो आंतरिक लेखांकन दर बा, एगो फर्श, गारंटी या भविष्य के मूल्य के वादा ना.',
    pegDesc2: 'विकेन्द्रीकृत एक्सचेंजों पर टोकन ट्रेडिंग, तरलता पूल के साथ कई चेन में समान 0.001 आधार मूल्य से बीज । खुले बाजार में, कीमत ट्रेडिंग द्वारा निर्धारित की जाती है — DeHub द्वारा नहीं — जेकर मतलब बा कि DeHub टोकन किसी भी समय इन-ऐप पेग से ऊपर या उससे नीचे की ट्रेडिंग की जा सकती है । डेहब डीईएक्स पर आपन आधिकारिक तरलता बीज करेला ताकि हर लेनदेन के सार्वजनिक रूप से चेन पर सत्यापित कइल जा सके.',
